const input = $input.first().json;
const agentResponse = input.output || input.fallbackResponse || input.text || 'Lo siento, no pude procesar tu mensaje.';

let normalizedData;
try {
  normalizedData = $('Normalizador de Payload').first().json;
} catch (e) {
  normalizedData = { userId: input.userId || 'unknown', provider: input.provider || 'evolution' };
}

const provider = normalizedData.provider || 'evolution';
const userId = normalizedData.userId || 'unknown';

function formatForEvolution(userId, responseText) {
  return {
    number: userId,
    text: responseText,
    options: { delay: 1200, presence: "composing" }
  };
}

function formatForSendPulse(userId, responseText, botId) {
  return {
    bot_id: botId,
    phone: userId.startsWith('+') ? userId : '+' + userId,
    message: { type: "text", text: { body: responseText } }
  };
}

const safeResponse = agentResponse.length > 4096 ? agentResponse.substring(0, 4000) + '\n\n_(Mensaje truncado)_' : agentResponse;

let outboundPayload;
if (provider === 'evolution') {
  outboundPayload = formatForEvolution(userId, safeResponse);
} else if (provider === 'sendpulse') {
  outboundPayload = formatForSendPulse(userId, safeResponse, normalizedData.instanceId);
} else {
  outboundPayload = formatForEvolution(userId, safeResponse);
}

return [{
  json: {
    provider: provider,
    userId: userId,
    responseText: safeResponse,
    outboundPayload: outboundPayload,
    timestamp: new Date().toISOString()
  }
}];

// 1. Extraer el payload entrante (contemplando si viene anidado en .body o directo)
const raw = $input.first().json;
const body = raw.body || raw;
const data = body.data || body;
const key = data.key || {};
const message = data.message || {};

// 2. Guard Rail 1: Prevenir auto-respuestas si el mensaje fue enviado por vos mismo
if (key.fromMe === true) {
  return []; // Detiene la ejecución inmediatamente
}

// 3. Guard Rail 2: Ignorar grupos de WhatsApp
const remoteJid = key.remoteJid || '';
if (remoteJid.endsWith('@g.us')) {
  return [];
}

// 4. Si viene de Evolution API
if (body.data || body.event === 'messages.upsert' || key.remoteJid) {
  // Extraer texto según el tipo de mensaje de Baileys/Evolution
  let text = message.conversation || 
             message.extendedTextMessage?.text || 
             message.imageMessage?.caption || 
             message.videoMessage?.caption || '';

  let type = 'text';
  let mediaUrl = null;
  let mimeType = null;

  if (message.imageMessage) {
    type = 'image';
    mimeType = message.imageMessage.mimetype;
  } else if (message.audioMessage) {
    type = 'audio';
    mimeType = message.audioMessage.mimetype;
  }

  // Si no hay texto ni multimedia soportada (por ejemplo, sticker o reacción), descartar
  if (!text.trim() && type === 'text') {
    return [];
  }

  // Extraer número de teléfono limpio
  const senderNumber = remoteJid.replace('@s.whatsapp.net', '');

  return [{
    json: {
      userId: senderNumber,
      senderJid: remoteJid,
      userName: data.pushName || 'Usuario',
      messageType: type,
      messageContent: text,
      mediaUrl: mediaUrl,
      mediaCaption: message.imageMessage?.caption || null,
      mediaMimeType: mimeType,
      timestamp: new Date().toISOString(),
      messageId: key.id || null,
      fromMe: false,
      instanceId: body.instance || 'bot-whatsapp',
      provider: 'evolution',
      rawPayload: body
    }
  }];
}

// 5. Fallback por si llega otro proveedor
return [{
  json: {
    userId: 'unknown',
    userName: 'Unknown',
    messageType: 'unknown',
    messageContent: '[Proveedor no reconocido]',
    provider: 'unknown',
    rawPayload: body
  }
}];

const nombreProducto = (query || '').toLowerCase().trim();

if (!nombreProducto) {
  return 'No se especificó ningún producto para consultar.';
}

const inventario = {
  'crema facial': { disponible: true, cantidad: 25, precio: 45.00 },
  'serum vitamina c': { disponible: true, cantidad: 12, precio: 65.00 },
  'protector solar': { disponible: true, cantidad: 50, precio: 35.00 },
  'mascarilla hidratante': { disponible: false, cantidad: 0, precio: 28.00 }
};

let producto = null;
let nombreEncontrado = '';

for (const [nombre, datos] of Object.entries(inventario)) {
  if (nombre.includes(nombreProducto) || nombreProducto.includes(nombre)) {
    producto = datos;
    nombreEncontrado = nombre;
    break;
  }
}

if (!producto) {
  return `No encontramos "${nombreProducto}". Productos disponibles: ${Object.keys(inventario).join(', ')}.`;
}

return producto.disponible
  ? `SI HAY STOCK de "${nombreEncontrado}". Quedan ${producto.cantidad} unidades. Precio: $${producto.precio}.`
  : `NO HAY STOCK de "${nombreEncontrado}". Precio de referencia: $${producto.precio}.`;

const input = $input.first().json;
const messageType = input.messageType || 'unknown';
const userName = input.userName || 'Usuario';

const fallbackMessages = {
  document: `¡Hola ${userName}! 📄 Recibimos tu documento. Por el momento procesamos texto, imágenes y mensajes de voz.`,
  sticker: `¡${userName}! 😄 No puedo interpretar stickers todavía. Por favor escríbeme un mensaje de texto.`,
  video: `¡Hola ${userName}! 🎥 Por ahora no procesamos videos directamente, pero cuéntame de qué se trata por texto.`,
  unknown: `¡Hola ${userName}! 🤔 No pudimos procesar este tipo de mensaje. Intenta enviando texto, imagen o audio.`
};

const fallbackResponse = fallbackMessages[messageType] || fallbackMessages['unknown'];

return [{
  json: {
    ...input,
    fallbackResponse: fallbackResponse,
    output: fallbackResponse,
    isFallback: true
  }
}];

const input = $input.first().json;

console.log('--- REGISTRO DE SALIDA ---');
console.log('Proveedor:', input.provider);
console.log('Usuario:', input.userId);
console.log('Respuesta:', input.responseText);
console.log('Timestamp:', input.timestamp);

return [{ json: { status: 'success', loggedAt: new Date().toISOString() } }];

